/* Cashier layouts follow the check-in, POS and connected-record Figma flows.
   Orders and signatures use the existing shared reservation model. */
(()=>{
 const base={handle,render,overlay:renderOverlay,checkin:checkinPage,receipt:posReceiptPage};
 const chip=(text,blue=false)=>'<span class="pos-chip '+(blue?'blue':'')+'">'+esc(text)+'</span>';
 const row=(label,value)=>'<div class="pos-detail-row"><span>'+label+'</span><strong>'+value+'</strong></div>';
 const stage=()=>state.ui.arrivalStage||ops().arrivalStage||'scan';
 function setStage(value){state.ui.arrivalStage=value;ops().arrivalStage=value;save();render();}
 function help(active){return '<aside class="checkin-help"><h2>How it works</h2>'+[['Scan guest QR','Scan the QR pass from the guest’s e-mail or phone'],['Confirm stay and room','Check the guest, the reservation and the room'],['Checked in','The reservation is updated for the whole team']].map(([title,text],i)=>'<div class="checkin-help-step"><b class="'+(active===i?'active':'')+'">'+(i+1)+'</b><div><h3>'+title+'</h3><p>'+text+'</p></div></div>').join('')+'</aside>';}
 function guestCard(r){return '<article class="checkin-card"><header><span class="pos-avatar">'+esc(v2Full(r.guest).split(' ').map(x=>x[0]).join(''))+'</span><div><h2>'+esc(v2Full(r.guest))+'</h2><div class="row">'+chip(r.type,true)+chip(r.checkedIn?'Checked in':'Confirmed')+'</div></div></header>'+row('Reservation','#'+r.id+' · Group '+esc(state.request.organization))+row('Stay',dates()+' · '+nights()+' nights')+row('Room',esc(r.unit)+' '+button('Change','cx-arrival-change','pos-text-button'))+row('Balance due',money(stayBalance(r)))+'</article>';}
 checkinPage=function(){const s=stage(),r=activePosGuest();let left='';
  if(s==='scan')left='<section class="checkin-scanner"><h2>'+(ops().scanPending?'Scanning…':'Ready to scan')+'</h2><button class="scan-frame" data-action="v4-scan" aria-label="Scan guest QR pass" '+(ops().scanPending?'disabled':'')+'>'+img('c431f.svg','Guest QR pass')+['a30ad.svg','7575e.svg','67093.svg','46b54.svg'].map((asset,i)=>img(asset,'','scan-corner corner-'+i)).join('')+'</button><p>'+(ops().scanPending?'Reading the guest’s pass…':'Position the guest’s QR code within the frame')+'</p><div class="scan-trouble"><span>Having trouble scanning?</span>'+button('Enter reservation #','cx-find-reservation','pos-outline')+'</div></section>';
  else if(s==='find')left='<section class="checkin-confirm"><div>'+button('← Back to scanner','v4-scan-back','pos-text-button')+'</div><h2>Find reservation</h2><p>Type the reservation number or the guest name</p><input class="pos-search find-reservation-search" name="v4-find" placeholder="Reservation # or guest name" aria-label="Find reservation"><div class="v4-find-results">'+connectedGuests().filter(r=>r.paid&&!r.checkedOut).map(r=>'<article class="v4-find-result"><div><h3>'+esc(v2Full(r.guest))+'</h3><p>#'+r.id+' · '+esc(r.type)+' · '+esc(r.unit)+'</p></div>'+button('Select','cx-arrival-'+r.id,'primary')+'</article>').join('')+'<p class="v4-no-results" hidden>No reservations found.</p></div></section>';
  else if(s==='confirm')left='<section class="checkin-confirm"><div class="row between">'+button('← Back','v4-scan-back','pos-text-button')+button('New scan','cx-pos-scan','pos-text-button')+'</div><h2>Confirm check-in</h2><p>Please confirm the details before recording the arrival</p>'+guestCard(r)+'<h3>Visit details</h3><article class="checkin-card">'+row('Date & time','Nov 12, 2026 · 3:45 PM')+row('Checked in by',esc(ops().staff)+' (Front desk)')+'</article><div class="checkin-actions">'+button('Continue to waiver','cx-waiver','primary')+'</div></section>';
  else if(s==='waiver')left='<section class="checkin-confirm"><div class="row between">'+button('← Back','v4-confirm-back','pos-text-button')+button('New scan','cx-pos-scan','pos-text-button')+'</div><h2>Stay waiver</h2><p>Please read and sign to complete check-in</p><article class="checkin-card waiver-terms"><h3>1. Property rules</h3><p>Guests agree to follow the venue rules, including quiet hours from 10:00 PM to 7:00 AM.</p><h3>2. Responsibility</h3><p>The venue is not responsible for items left unattended. Damage to rooms may be charged to the reservation.</p><h3>3. Safety</h3><p>Guests will follow posted safety instructions on trails and in shared spaces.</p></article><form id="cx-waiver-form">'+field('Guest signature','signature',v2Full(r.guest),'text','required')+'<div class="waiver-signature" id="cx-waiver-preview">'+esc(v2Full(r.guest))+'</div>'+check('I agree to the stay terms','agree',false,'required')+'<div class="checkin-actions">'+button('Sign and check in','cx-sign-checkin','primary')+'</div></form></section>';
  else left='<section class="checkin-complete"><span class="checkin-success" aria-label="Success">✓</span><h2>Checked in</h2><p>'+esc(v2Full(r.guest))+' is checked in to '+esc(r.unit)+'</p><article class="checkin-card">'+row('Reservation','#'+r.id)+row('Room',esc(r.unit))+row('Checked in','Nov 12, 2026 · 3:45 PM')+row('Status',chip('Checked in'))+'</article><p class="checkin-note">Reservation #'+r.id+' now shows Checked in for the whole team.</p><div class="checkin-actions">'+button('Check in another guest','cx-pos-scan','pos-outline')+button('Open reservation','v2-record-'+r.id,'primary')+'</div></section>';
  return '<div class="pos-app checkin-app"><header class="checkin-heading"><div><h1>Check-in</h1><p>Scan the guest’s QR pass to check them in</p></div>'+button('Search reservation ⌕','cx-find-reservation','checkin-search')+'</header><div class="checkin-layout">'+left+help(['scan','find'].includes(s)?0:s==='done'?2:1)+'</div>'+posFooter()+'</div>';
 };
 posFooter=function(){const current=state.ui.admin,active=current==='pos-arrival'?'Check-in':current==='pos-completed'?'Completed':'Reservations';const icons=["<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 5h18v16H3z M7 3v4 M17 3v4 M3 10h18\"/></svg>","<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M8 3h8v4h4v14H4V7h4z M8 12h8 M8 16h5\"/></svg>","<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 5h16v16H4z M7 12l3 3 6-6\"/></svg>","<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 3h12v18l-3-2-3 2-3-2-3 2z M9 8h6 M9 12h6\"/></svg>","<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 8V3h5 M16 3h5v5 M21 16v5h-5 M8 21H3v-5 M7 12l3 3 7-7\"/></svg>","<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2\"/></svg>"];return '<nav class="pos-bottom" aria-label="Cashier navigation">'+[['Availability Grid','cx-pos-availability'],['Reservations','cx-pos'],['Completed','cx-pos-completed'],['Invoices','cx-pos-invoices'],['Check-in','cx-pos-scan'],['Settings','cx-pos-settings']].map(([title,action],i)=>button('<span aria-hidden="true">'+icons[i]+'</span> '+title,action,title===active?'active':'')).join('')+'</nav>';};
 posReservations=function(){const completed=state.ui.admin==='pos-completed',list=connectedGuests().filter(r=>r.paid&&(completed?r.checkedOut:!r.checkedOut));return '<div class="pos-app pos-list-app"><div class="pos-content"><h1>'+(completed?'Completed':'Reservations')+'</h1><p>Find the guest to add charges to their stay</p><div class="pos-list-tools"><input class="pos-search" name="pos-search" placeholder="Search guest, room or reservation" aria-label="Search reservations"><label>Sort by: <select name="v4-sort"><option value="room">Room number</option><option value="guest">Guest name</option></select></label></div><div class="table-wrap"><table class="pos-reservation-table"><thead><tr>'+['RESERVATION','GUEST','GROUP','ROOM','STATUS','BALANCE',''].map(t=>'<th>'+t+'</th>').join('')+'</tr></thead><tbody>'+list.sort((a,b)=>ops().sort==='guest'?v2Full(a.guest).localeCompare(v2Full(b.guest)):a.unit.localeCompare(b.unit,undefined,{numeric:true})).map(r=>'<tr class="pos-reservation" data-room="'+esc(r.unit)+'"><td>#'+r.id+'</td><td><b>'+esc(v2Full(r.guest))+'</b><small>'+(r.checkedOut?'Checked out Nov 15':r.checkedIn?'Checked in Nov 12 · 3:45 PM':'Arrives Nov 12')+'</small></td><td>'+esc(state.request.organization)+'</td><td>'+esc(r.type)+' · '+esc(r.unit)+'</td><td>'+chip(r.checkedOut?'Checked out':r.checkedIn?'Checked in':'Confirmed',!r.checkedIn)+'</td><td>'+money(stayBalance(r))+'</td><td>'+button('Open',completed?'v2-record-'+r.id:'cx-pos-guest-'+r.id,'primary')+'</td></tr>').join('')+'</tbody></table></div></div>'+posFooter()+'</div>';};
 posReceiptPage=function(){const o=ops().orders.find(x=>x.id===ops().lastOrder),r=activePosGuest();return posShell('Checkout','<div class="pos-amount">'+money(o.total)+'<small>total</small></div><div class="pos-checkout-columns"><section><h3>Adjust</h3>'+line('Tip',money(o.tip))+line('Discount',money(o.discount))+'</section><section><h3>Items</h3>'+o.items.map(x=>line(x.qty+'× '+x.title,money(x.qty*x.price))).join('')+line('Tax (10%)',money(o.tax))+line('Total',money(o.total),'total')+'</section><section><h3>Pay</h3>'+button(o.status,'cx-pos','primary wide-btn')+'<p>'+esc(v2Full(r.guest))+' · Res #'+r.id+'</p></section></div>');};
 renderOverlay=function(){base.overlay();if(state.ui.video===4&&modal?.startsWith('cx-')){const overlay=$('#overlay');overlay.innerHTML=overlay.innerHTML.replace(/<p class="payment-demo">[\s\S]*?<\/p>/,'').replace('Change demo payment card','Change payment card').replace('Demo payment','Payment').replace('Confirm demo payment','Confirm payment').replace('Save demo card','Save card').replace('Demo signature · Nov 12, 2026','Signed electronically · Nov 12, 2026');}if(state.ui.app==='admin'&&state.ui.admin==='pos-receipt'&&!modal){const o=ops().orders.find(x=>x.id===ops().lastOrder),r=activePosGuest();$('#overlay').innerHTML='<div class="modal-backdrop"><section class="modal pos-receipt-dialog" role="dialog" aria-modal="true" aria-label="'+esc(o.status)+'"><div class="modal-content"><span class="checkin-success">✓</span><h2>'+esc(o.status)+'</h2><p>'+esc(v2Full(r.guest))+' · '+esc(r.type)+' · '+esc(r.unit)+'</p><strong>'+money(o.total)+'</strong><p>Order '+o.id+' was added to Reservation #'+r.id+'</p><p>Balance due on the stay: '+money(stayBalance(r))+'</p></div><footer class="modal-footer">'+button('New order','cx-pos-new')+button('Open reservation','v2-record-'+r.id,'primary')+'</footer></section></div>';}};
 function itemPage(){const p=posProducts.find(x=>x.id===ops().item),d=state.ui.posItemDraft;const choices=p.id==='steak'?['Rare','Med-Rare','Medium','Med-Well','Well','Pittsburgh / Charred','Blue','Char-grilled']:p.id==='coffee'?['Regular · Hot','Decaf · Hot','Regular · Iced']:['Standard'];return posShell(p.title,'<form id="cx-item-form" class="pos-options"><section><h3>'+(p.id==='steak'?'Cooking temperature':'Style')+'</h3><div class="pos-option-grid">'+choices.map(t=>'<label class="'+(d.temperature===t?'selected':'')+'"><input type="radio" name="temperature" value="'+t+'" '+(d.temperature===t?'checked':'')+'>'+t+'</label>').join('')+'</div>'+(p.id==='steak'?'<p class="hint mt">Included: 8 oz grass-fed beef · seasonal vegetables</p>':'')+'</section><aside><div class="pos-quantity">'+button('−','v4-qty-down')+'<output>'+d.qty+'</output><input type="hidden" name="qty" value="'+d.qty+'">'+button('+','v4-qty-up')+'</div>'+(p.id==='steak'?'<div class="v4-cooking-summary"><span>Cooking temps</span><span>'+esc(d.temperature)+'</span></div>':'')+select('Sauce','sauce',d.sauce||'Choose',['Choose','Peppercorn','Garlic butter','Mushroom'])+select('Seat','seat',d.seat,['Seat 1','Seat 2','Seat 3','Seat 4'])+select('Course','course',d.course,['Main course','Starter','Dessert','Drink'])+'<div class="pos-option-actions">'+(d.showNote?field('Add note','note',d.note,'text','maxlength="120"'):button('Add note','v4-item-note'))+button('Add · '+money(p.price*d.qty),'v4-item-save','primary')+'</div></aside></form>','v4-item-cancel');}
 render=function(){if(state.ui.app==='admin'&&state.ui.admin==='pos-item'){$('#demo').innerHTML=demoBar();$('#app').innerHTML=itemPage();renderOverlay();return;}base.render();};
 function captureItem(){const f=$('#cx-item-form');if(f?.elements)Object.assign(state.ui.posItemDraft,Object.fromEntries(new FormData(f)));}
 handle=function(a,el){try{
  if(a==='cx-find-reservation'&&state.ui.admin==='pos-arrival')return setStage('find');
  if(a==='cx-pos-scan'){state.ui.arrivalStage='scan';ops().scanPending=false;}
  if(a==='v4-scan-back'){ops().scanPending=false;return setStage('scan');}
  if(a==='v4-confirm-back')return setStage('confirm');
  if(a==='cx-waiver'){state.ui.arrivalStage='waiver';}
  if(a==='cx-sign-checkin'){base.handle(a,el);if(activePosGuest()?.checkedIn)return setStage('done');return;}
  if(a.startsWith('cx-arrival-')&&a!=='cx-arrival-change'){state.ui.arrivalStage='confirm';modal=null;}
  if(a==='v4-scan'){if(ops().scanPending)return;const r=activePosGuest();requireState(r&&!r.checkedOut,'Choose an active reservation.');const operation=ops();operation.scanPending=true;render();setTimeout(()=>{if(state.operations!==operation||!operation.scanPending)return;operation.scanPending=false;if(state.ui.admin==='pos-arrival')setStage('confirm');},1600);return;}
  if(a.startsWith('cx-item-')&&a!=='cx-item-save'){const p=posProducts.find(x=>x.id===a.slice(8));requireState(p,'Item unavailable.');ops().item=p.id;state.ui.posItemDraft={qty:1,temperature:p.id==='steak'?'Medium':p.id==='coffee'?'Regular · Hot':'Standard',seat:'Seat 1',course:p.id==='coffee'?'Drink':'Main course',note:''};return navigate('admin','pos-item');}
  if(a==='v4-item-note'){captureItem();state.ui.posItemDraft.showNote=true;save();render();return;}
  if(a==='v4-qty-up'||a==='v4-qty-down'){captureItem();const d=state.ui.posItemDraft;d.qty=Math.min(20,Math.max(1,Number(d.qty)+(a.endsWith('up')?1:-1)));save();render();return;}
  if(a==='v4-item-cancel')return navigate('admin','pos-order');
  if(a==='v4-item-save'||a==='cx-item-save'&&state.ui.admin==='pos-item'){const values=formValues('#cx-item-form');if(values.sauce&&values.sauce!=='Choose')values.note=[values.sauce,values.note].filter(Boolean).join(' · ');addPosItem(ops().item,values);return navigate('admin','pos-order');}
  return base.handle(a,el);
 }catch(error){toast(error.message,true);}};
 document.addEventListener('input',e=>{if(e.target.name==='v4-find'){const q=e.target.value.trim().toLowerCase();let matches=0;document.querySelectorAll('.v4-find-result').forEach(row=>{row.hidden=!row.textContent.toLowerCase().includes(q);if(!row.hidden)matches++;});$('.v4-no-results').hidden=!!matches;}});
 document.addEventListener('change',e=>{if(e.target.name==='v4-sort'){ops().sort=e.target.value;save();render();}if(state.ui.admin==='pos-item'&&e.target.closest('#cx-item-form')){captureItem();save();render();}});
 render();
})();
